            Ok(child) => child,
            Err(error) => {
                tracing::warn!(%error, host, "could not stage project extension; using sentinel fallback");
                return None;
            }
        };
        let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
        let mut stdin = child.stdin.take();
