    fn state() -> AppState {
        state_with_stt(None)
    }

    fn state_with_stt(stt: Option<String>) -> AppState {
        let board = Switchboard::new(
            Registry::new(vec![]),
            "pi".into(),
            None,
            "".into(),
            None,
            None,
            None,
            "medium".into(),
            ".cache".into(),
            true,
            "".into(),
            "".into(),
            "".into(),
            "".into(),
            HashMap::new(),
        );
        AppState::new(
            board,
            TranscriptLog::new(10),
